359	/// Export to a paged target format.
360	fn export_paged(
361	    document: &PagedDocument,
362	    config: &CompileConfig,
363	) -> SourceResult<Vec<Output>> {
364	    match config.output_format {
365	        OutputFormat::Pdf => {
366	            export_pdf(document, config).map(|()| vec![config.output.clone()])
367	        }
368	        OutputFormat::Png => {
369	            export_image(document, config, ImageExportFormat::Png).at(Span::detached())
370	        }
371	        OutputFormat::Svg => {
372	            export_image(document, config, ImageExportFormat::Svg).at(Span::detached())
373	        }
374	        OutputFormat::Html | OutputFormat::Bundle => unreachable!(),
375	    }
376	}
