536	mod output_template {
537	    const INDEXABLE: [&str; 3] = ["{p}", "{0p}", "{n}"];
538	
539	    pub fn has_indexable_template(output: &str) -> bool {
540	        INDEXABLE.iter().any(|template| output.contains(template))
541	    }
542	
543	    pub fn format(output: &str, this_page: usize, total_pages: usize) -> String {
544	        // Find the base 10 width of number `i`
545	        fn width(i: usize) -> usize {
546	            1 + i.checked_ilog10().unwrap_or(0) as usize
547	        }
548	
549	        let other_templates = ["{t}"];
550	        INDEXABLE.iter().chain(other_templates.iter()).fold(
551	            output.to_string(),
552	            |out, template| {
553	                let replacement = match *template {
554	                    "{p}" => format!("{this_page}"),
555	                    "{0p}" | "{n}" => format!("{:01$}", this_page, width(total_pages)),
556	                    "{t}" => format!("{total_pages}"),
557	                    _ => unreachable!("unhandled template placeholder {template}"),
558	                };
559	                out.replace(template, replacement.as_str())
560	            },
561	        )
562	    }
563	}
